/// Bytes of a sealed graph are carried in the durable envelope and also have
/// their own checksum.  The second checksum lets a manager distinguish a bad
/// graph body from a bad catalog/payload envelope in its repair receipt.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub(crate) struct VectorPartitionGraphBytes {
    pub(crate) bytes: Vec<u8>,
    pub(crate) checksum: [u8; 32],
}

#[derive(Deserialize)]
struct BorrowedVectorPartitionGraphBytes<'a> {
    #[serde(borrow)]
    bytes: &'a [u8],
    checksum: [u8; 32],
}

#[derive(Deserialize)]
struct BorrowedVectorPartitionBaseGenerationRecord<'a> {
    index: VectorIndexRef,
    partition_key: VectorPartitionKey,
    generation_id: u64,
    base_tx: TxId,
    base_lsn: Lsn,
    highest_included_tx: TxId,
    highest_included_lsn: Lsn,
    dimension: u32,
    quantization: VectorQuantization,
    algorithm_version: u16,
    graph_format_version: u16,
    #[serde(borrow)]
    graph: BorrowedVectorPartitionGraphBytes<'a>,
    state_digest: [u8; 32],
}

impl BorrowedVectorPartitionBaseGenerationRecord<'_> {
    fn into_owned(self) -> VectorPartitionBaseGenerationRecord {
        VectorPartitionBaseGenerationRecord {
            index: self.index,
            partition_key: self.partition_key,
            generation_id: self.generation_id,
            base_tx: self.base_tx,
            base_lsn: self.base_lsn,
            highest_included_tx: self.highest_included_tx,
            highest_included_lsn: self.highest_included_lsn,
            dimension: self.dimension,
            quantization: self.quantization,
            algorithm_version: self.algorithm_version,
            graph_format_version: self.graph_format_version,
            graph: VectorPartitionGraphBytes {
                // Copy once at the final length. Serde's Vec decoder grows
                // geometrically beyond its initial capped reservation,
                // retaining excess capacity and overlapping reallocations.
                bytes: self.graph.bytes.to_vec(),
                checksum: self.graph.checksum,
            },
            state_digest: self.state_digest,
        }
    }
}

