    pub fn append_trigger_audit(&self, index: u64, entry: &TriggerAuditEntry) -> Result<()> {
        self.with_db(|db| {
            let write_txn = db.begin_write().map_err(Self::storage_error)?;
            let mut identity_mutations = Vec::new();
            {
                let mut table = write_txn
                    .open_table(TRIGGER_AUDIT_TABLE)
                    .map_err(Self::storage_error)?;
                let key = Self::trigger_audit_key(index, &entry.trigger_name);
                let encoded = Self::encode(entry)?;
                table
                    .insert(key.as_str(), encoded.as_slice())
                    .map_err(Self::storage_error)?;
                let mut stamps = write_txn
                    .open_table(TRIGGER_AUDIT_STAMPS_TABLE)
                    .map_err(Self::storage_error)?;
                let stamped_at = Wallclock::now().0;
                stamps
                    .insert(key.as_str(), stamped_at)
                    .map_err(Self::storage_error)?;
                identity_mutations.push(content_identity::status_mutation(
                    b"trigger-audit",
                    key.as_bytes(),
                    &encoded,
                ));
                identity_mutations.push(content_identity::status_mutation(
                    b"trigger-stamp",
                    key.as_bytes(),
                    &stamped_at.to_le_bytes(),
                ));
            }
            {
                let mut config_table = write_txn
                    .open_table(CONFIG_TABLE)
                    .map_err(Self::storage_error)?;
                let mut ring: Vec<TriggerAuditEntry> = config_table
                    .get(TRIGGER_AUDIT_RING_CONFIG_KEY)
                    .map_err(Self::storage_error)?
                    .map(|value| Self::decode(value.value()))
                    .transpose()?
                    .unwrap_or_default();
                ring.push(entry.clone());
                let overflow = ring
                    .len()
                    .saturating_sub(crate::database::trigger::TRIGGER_AUDIT_RING_CAPACITY);
                if overflow > 0 {
                    ring.drain(0..overflow);
                }
                let current_next_index = config_table
                    .get(TRIGGER_AUDIT_NEXT_INDEX_CONFIG_KEY)
                    .map_err(Self::storage_error)?
                    .map(|value| Self::decode::<u64>(value.value()))
                    .transpose()?
                    .unwrap_or(0);
                let next_index = index.saturating_add(1).max(current_next_index);
                let encoded_ring = Self::encode(&ring)?;
                config_table
                    .insert(TRIGGER_AUDIT_RING_CONFIG_KEY, encoded_ring.as_slice())
                    .map_err(Self::storage_error)?;
                identity_mutations.extend(content_identity::config_mutations(
                    TRIGGER_AUDIT_RING_CONFIG_KEY,
                    Some(&encoded_ring),
                ));
                let encoded_next_index = Self::encode(&next_index)?;
                config_table
                    .insert(
                        TRIGGER_AUDIT_NEXT_INDEX_CONFIG_KEY,
                        encoded_next_index.as_slice(),
                    )
                    .map_err(Self::storage_error)?;
                identity_mutations.extend(content_identity::config_mutations(
                    TRIGGER_AUDIT_NEXT_INDEX_CONFIG_KEY,
                    Some(&encoded_next_index),
                ));
            }
            Self::apply_content_identity_mutations_in_write(
                &write_txn,
                &identity_mutations,
                &mut self.proof_admission(),
            )?;
            write_txn.commit().map_err(Self::storage_error)?;
            Ok(())
        })
    }

    pub fn remove_table_data(&self, name: &str) -> Result<()> {
        let rows = self.load_relational_table(name)?;
        let sources = self.load_sync_source_lsns()?;
        self.with_db(|db| {
            let write_txn = db.begin_write().map_err(Self::storage_error)?;
            let table_name = Self::rel_table_name(name);
            let table_def: TableDefinition<&[u8], &[u8]> =
                TableDefinition::new(table_name.as_str());
            match write_txn.delete_table(table_def) {
                Ok(_) | Err(redb::TableError::TableDoesNotExist(_)) => {}
                Err(redb::TableError::TableTypeMismatch { .. }) => {}
                Err(err) => return Err(Self::storage_error(err)),
            }
            let legacy_table_def: TableDefinition<u64, &[u8]> =
                TableDefinition::new(table_name.as_str());
            match write_txn.delete_table(legacy_table_def) {
                Ok(_) | Err(redb::TableError::TableDoesNotExist(_)) => {}
                Err(redb::TableError::TableTypeMismatch { .. }) => {}
                Err(err) => return Err(Self::storage_error(err)),
            }
            Self::remove_sync_source_provenance_for_table(&write_txn, name)?;
            Self::remove_retention_expiries_for_table(&write_txn, name)?;
            let mut mutations = rows
                .iter()
                .map(|row| content_identity::remove_row_mutation(name, row.row_id))
                .collect::<Vec<_>>();
            for row in &rows {
                let key =
                    crate::composite_store::retention_expiry_key(name, row.row_id, row.created_tx);
                mutations.extend(content_identity::config_mutations(&key, None));
            }
            mutations.extend(sources.keys().filter(|(table, _)| table == name).map(
                |(table, row_id)| content_identity::remove_sync_source_mutation(table, *row_id),
            ));
            Self::apply_content_identity_mutations_in_write(
                &write_txn,
                &mutations,
                &mut self.proof_admission(),
            )?;
            write_txn.commit().map_err(Self::storage_error)?;
            Ok(())
        })
    }

    pub fn remove_table_with_config_values_and_ddl_log(
        &self,
        name: &str,
        config_values: Vec<(&str, Vec<u8>)>,
        lsn: Lsn,
        ddl: &[DdlChange],
    ) -> Result<()> {
        let rows = self.load_relational_table(name)?;
        let sources = self.load_sync_source_lsns()?;
        self.with_db(|db| {
            let write_txn = db.begin_write().map_err(Self::storage_error)?;
            let mut identity_mutations = content_identity::remove_schema_mutations(name);
            identity_mutations.extend(
                rows.iter()
                    .map(|row| content_identity::remove_row_mutation(name, row.row_id)),
            );
            identity_mutations.extend(sources.keys().filter(|(table, _)| table == name).map(
                |(table, row_id)| content_identity::remove_sync_source_mutation(table, *row_id),
            ));
            for row in &rows {
                let key =
                    crate::composite_store::retention_expiry_key(name, row.row_id, row.created_tx);
                identity_mutations.extend(content_identity::config_mutations(&key, None));
            }
            {
                let mut meta_table = write_txn
                    .open_table(META_TABLE)
                    .map_err(Self::storage_error)?;
                let key = Self::meta_key(name);
                meta_table
                    .remove(key.as_str())
                    .map_err(Self::storage_error)?;
            }
            let table_name = Self::rel_table_name(name);
            let table_def: TableDefinition<&[u8], &[u8]> =
                TableDefinition::new(table_name.as_str());
            match write_txn.delete_table(table_def) {
                Ok(_) | Err(redb::TableError::TableDoesNotExist(_)) => {}
                Err(redb::TableError::TableTypeMismatch { .. }) => {}
                Err(err) => return Err(Self::storage_error(err)),
            }
            let legacy_table_def: TableDefinition<u64, &[u8]> =
                TableDefinition::new(table_name.as_str());
            match write_txn.delete_table(legacy_table_def) {
                Ok(_) | Err(redb::TableError::TableDoesNotExist(_)) => {}
                Err(redb::TableError::TableTypeMismatch { .. }) => {}
                Err(err) => return Err(Self::storage_error(err)),
            }
            Self::remove_sync_source_provenance_for_table(&write_txn, name)?;
            Self::remove_retention_expiries_for_table(&write_txn, name)?;
            if !config_values.is_empty() {
                let mut config_table = write_txn
                    .open_table(CONFIG_TABLE)
                    .map_err(Self::storage_error)?;
                for (key, encoded) in config_values {
                    Self::update_policy_hold_release_index(&write_txn, key, true)?;
                    config_table
                        .insert(key, encoded.as_slice())
                        .map_err(Self::storage_error)?;
                    identity_mutations
                        .extend(content_identity::config_mutations(key, Some(&encoded)));
                }
            }
            if !ddl.is_empty() {
                let mut ddl_table = write_txn
                    .open_table(DDL_LOG_TABLE)
                    .map_err(Self::storage_error)?;
                for (index, change) in ddl.iter().enumerate() {
                    let key = Self::ddl_log_key_for_index(lsn, index, ddl.len());
                    let encoded = Self::encode(change)?;
                    ddl_table
                        .insert(key.as_str(), encoded.as_slice())
                        .map_err(Self::storage_error)?;
                    identity_mutations
                        .push(content_identity::encoded_history_mutation(&key, change)?);
                }
            }
            Self::apply_content_identity_mutations_in_write(
                &write_txn,
                &identity_mutations,
                &mut self.proof_admission(),
            )?;
            write_txn.commit().map_err(Self::storage_error)?;
            Ok(())
        })
    }

    pub fn remove_table_rewrite_aux_with_config_values_and_ddl_log(
        &self,
        name: &str,
        config_values: Vec<(&str, Vec<u8>)>,
        lsn: Lsn,
        ddl: &[DdlChange],
        graph_edges: &[AdjEntry],
    ) -> Result<()> {
        let rows = self.load_relational_table(name)?;
        let sources = self.load_sync_source_lsns()?;
        let table_meta = self.load_all_table_meta()?;
        let quantization = Self::vector_quantization_map(&table_meta);
        let removed_vectors = self
            .load_vectors()?
            .into_iter()
            .filter(|entry| entry.index.table == name)
            .collect::<Vec<_>>();
        self.with_db(|db| {
            let write_txn = db.begin_write().map_err(Self::storage_error)?;
            let mut identity_mutations = content_identity::remove_schema_mutations(name);
            identity_mutations.extend(
                rows.iter()
                    .map(|row| content_identity::remove_row_mutation(name, row.row_id)),
            );
            identity_mutations.extend(sources.keys().filter(|(table, _)| table == name).map(
                |(table, row_id)| content_identity::remove_sync_source_mutation(table, *row_id),
            ));
            for row in &rows {
                let key =
                    crate::composite_store::retention_expiry_key(name, row.row_id, row.created_tx);
                identity_mutations.extend(content_identity::config_mutations(&key, None));
            }
            identity_mutations.extend(removed_vectors.iter().map(|entry| {
                content_identity::remove_vector_mutation(
                    &entry.index,
                    entry.row_id,
                    quantization.get(&entry.index).copied().unwrap_or_default(),
                )
            }));
            identity_mutations.extend(removed_vectors.iter().map(|entry| {
                content_identity::remove_vector_version_mutation(
                    &entry.index,
                    entry.row_id,
                    entry.created_tx,
                    entry.lsn,
                    quantization.get(&entry.index).copied().unwrap_or_default(),
                )
            }));
            self.remove_vector_partition_records_matching_all_in_write(
                &write_txn,
                &|index: &VectorIndexRef| index.table == name,
            )?;
            self.remove_vector_entries_matching_in_write(&write_txn, &|index| index.table == name)?;
            {
                let mut meta_table = write_txn
                    .open_table(META_TABLE)
                    .map_err(Self::storage_error)?;
                let key = Self::meta_key(name);
                meta_table
                    .remove(key.as_str())
                    .map_err(Self::storage_error)?;
            }
            let table_name = Self::rel_table_name(name);
            let table_def: TableDefinition<&[u8], &[u8]> =
                TableDefinition::new(table_name.as_str());
            match write_txn.delete_table(table_def) {
                Ok(_) | Err(redb::TableError::TableDoesNotExist(_)) => {}
                Err(redb::TableError::TableTypeMismatch { .. }) => {}
                Err(err) => return Err(Self::storage_error(err)),
            }
            let legacy_table_def: TableDefinition<u64, &[u8]> =
                TableDefinition::new(table_name.as_str());
            match write_txn.delete_table(legacy_table_def) {
                Ok(_) | Err(redb::TableError::TableDoesNotExist(_)) => {}
                Err(redb::TableError::TableTypeMismatch { .. }) => {}
                Err(err) => return Err(Self::storage_error(err)),
            }
            Self::remove_sync_source_provenance_for_table(&write_txn, name)?;
            Self::remove_retention_expiries_for_table(&write_txn, name)?;

            let _ = write_txn.delete_table(GRAPH_FWD_TABLE);
            let _ = write_txn.delete_table(GRAPH_REV_TABLE);
            {
                let mut fwd_table = write_txn
                    .open_table(GRAPH_FWD_TABLE)
                    .map_err(Self::storage_error)?;
                let mut rev_table = write_txn
                    .open_table(GRAPH_REV_TABLE)
                    .map_err(Self::storage_error)?;
                for entry in graph_edges {
                    let encoded = Self::encode(entry)?;
                    let fwd_key = Self::graph_fwd_key(entry);
                    let rev_key = Self::graph_rev_key(entry);
                    fwd_table
                        .insert(fwd_key.as_slice(), encoded.as_slice())
                        .map_err(Self::storage_error)?;
                    rev_table
                        .insert(rev_key.as_slice(), encoded.as_slice())
                        .map_err(Self::storage_error)?;
                }
            }
            Self::reset_content_identity_families_in_write(
                &write_txn,
                &[content_identity::LogicalFamily::Graph],
                &mut self.proof_admission(),
            )?;
            let mut ordered_edges = graph_edges.iter().collect::<Vec<_>>();
            ordered_edges.sort_by_key(|entry| (entry.lsn, entry.created_tx));
            for entry in ordered_edges {
                identity_mutations.push(content_identity::edge_mutation(entry)?);
            }

            if !config_values.is_empty() {
                let mut config_table = write_txn
                    .open_table(CONFIG_TABLE)
                    .map_err(Self::storage_error)?;
                for (key, encoded) in config_values {
                    Self::update_policy_hold_release_index(&write_txn, key, true)?;
                    config_table
                        .insert(key, encoded.as_slice())
                        .map_err(Self::storage_error)?;
                    identity_mutations
                        .extend(content_identity::config_mutations(key, Some(&encoded)));
                }
            }
            if !ddl.is_empty() {
                let mut ddl_table = write_txn
                    .open_table(DDL_LOG_TABLE)
                    .map_err(Self::storage_error)?;
                for (index, change) in ddl.iter().enumerate() {
                    let key = Self::ddl_log_key_for_index(lsn, index, ddl.len());
                    let encoded = Self::encode(change)?;
                    ddl_table
                        .insert(key.as_str(), encoded.as_slice())
                        .map_err(Self::storage_error)?;
                    identity_mutations
                        .push(content_identity::encoded_history_mutation(&key, change)?);
                }
            }
            Self::apply_content_identity_mutations_in_write(
                &write_txn,
                &identity_mutations,
                &mut self.proof_admission(),
            )?;
            write_txn.commit().map_err(Self::storage_error)?;
            Ok(())
        })
    }

    pub fn rewrite_table_rows(&self, name: &str, rows: &[VersionedRow]) -> Result<()> {
        let table_meta = self.load_all_table_meta()?;
        let previous_rows = self.load_relational_table(name)?;
        let sources = self.load_sync_source_lsns()?;
        self.with_db(|db| {
            let write_txn = db.begin_write().map_err(Self::storage_error)?;
            {
                let table_name = Self::rel_table_name(name);
                let table_def: TableDefinition<&[u8], &[u8]> =
                    TableDefinition::new(table_name.as_str());
                let _ = write_txn.delete_table(table_def);
                let legacy_table_def: TableDefinition<u64, &[u8]> =
                    TableDefinition::new(table_name.as_str());
                let _ = write_txn.delete_table(legacy_table_def);
                let mut redb_table = write_txn
                    .open_table(table_def)
                    .map_err(Self::storage_error)?;
                for row in rows {
                    let encoded = Self::encode_versioned_row(row, table_meta.get(name))?;
                    let key = Self::rel_row_key(row);
                    redb_table
                        .insert(key.as_slice(), encoded.as_slice())
                        .map_err(Self::storage_error)?;
                }
            }
            if let Some(meta) = table_meta.get(name) {
                Self::rebuild_relational_indexes_in_write(
                    &write_txn,
                    &self.path,
                    name,
                    meta,
                    Some(rows),
                    &mut self.proof_admission(),
                )?;
            }
            Self::retain_sync_source_provenance_for_table_rows(&write_txn, name, rows)?;
            let mut mutations = previous_rows
                .iter()
                .map(|row| content_identity::remove_row_mutation(name, row.row_id))
                .collect::<Vec<_>>();
            let mut ordered_rows = rows.iter().collect::<Vec<_>>();
            ordered_rows.sort_by_key(|row| (row.lsn, row.created_tx));
            for row in ordered_rows {
                mutations.push(content_identity::row_mutation(
                    name,
                    row,
                    table_meta.get(name),
                )?);
            }
            let live_rows = rows
                .iter()
                .filter(|row| row.deleted_tx.is_none())
                .map(|row| row.row_id)
                .collect::<HashSet<_>>();
            mutations.extend(
                sources
                    .keys()
                    .filter(|(table, row_id)| table == name && !live_rows.contains(row_id))
                    .map(|(table, row_id)| {
                        content_identity::remove_sync_source_mutation(table, *row_id)
                    }),
            );
            Self::apply_content_identity_mutations_in_write(
                &write_txn,
                &mutations,
                &mut self.proof_admission(),
            )?;
            write_txn.commit().map_err(Self::storage_error)?;
            Ok(())
        })
    }

    pub fn rewrite_vectors(&self, vectors: &[VectorEntry]) -> Result<()> {
        let table_meta = self.load_all_table_meta()?;
        let vector_quantization = Self::vector_quantization_map(&table_meta);
        let previous_vectors = self.load_vectors()?;
        self.with_db(|db| {
            let write_txn = db.begin_write().map_err(Self::storage_error)?;
            let _ = write_txn.delete_table(VECTORS_TABLE);
            {
                let mut table = write_txn
                    .open_table(VECTORS_TABLE)
                    .map_err(Self::storage_error)?;
                for entry in vectors {
                    let quantization = vector_quantization
                        .get(&entry.index)
                        .copied()
                        .unwrap_or_default();
                    let encoded = Self::encode_vector_entry(entry, quantization)?;
                    let key = Self::vector_key(entry);
                    table
                        .insert(key.as_slice(), encoded.as_slice())
                        .map_err(Self::storage_error)?;
                }
            }
            Self::reset_content_identity_families_in_write(
                &write_txn,
                &[
                    content_identity::LogicalFamily::F32Vectors,
                    content_identity::LogicalFamily::Sq8Vectors,
                    content_identity::LogicalFamily::Sq4Vectors,
                ],
                &mut self.proof_admission(),
            )?;
            let mut mutations = previous_vectors
                .iter()
                .map(|entry| {
                    content_identity::remove_vector_version_mutation(
                        &entry.index,
                        entry.row_id,
                        entry.created_tx,
                        entry.lsn,
                        vector_quantization
                            .get(&entry.index)
                            .copied()
                            .unwrap_or_default(),
                    )
                })
                .collect::<Vec<_>>();
            for entry in vectors {
                let quantization = vector_quantization
                    .get(&entry.index)
                    .copied()
                    .unwrap_or_default();
                mutations.push(content_identity::vector_mutation(entry, quantization));
                mutations.push(content_identity::vector_version_mutation(
                    entry,
                    quantization,
                ));
            }
            Self::apply_content_identity_mutations_in_write(
                &write_txn,
                &mutations,
                &mut self.proof_admission(),
            )?;
            write_txn.commit().map_err(Self::storage_error)?;
            Ok(())
        })
    }

    pub fn rewrite_table_meta_rows_and_append_ddl_log(
        &self,
        name: &str,
        meta: &TableMeta,
        rows: &[VersionedRow],
        lsn: Lsn,
        ddl: &[DdlChange],
        config_values: Vec<(&str, Vec<u8>)>,
    ) -> Result<()> {
        let mut table_meta = self.load_all_table_meta()?;
        let previous_meta = table_meta.get(name).cloned();
        let previous_vector_quantization = Self::vector_quantization_map(&table_meta);
        let previous_rows = self.load_relational_table(name)?;
        let sources = self.load_sync_source_lsns()?;
        let previous_vectors = self
            .load_vectors()?
            .into_iter()
            .filter(|entry| entry.index.table == name)
            .collect::<Vec<_>>();
        table_meta.insert(name.to_string(), meta.clone());
        let vector_quantization = Self::vector_quantization_map(&table_meta);
        let previous_vector_columns = previous_meta
            .as_ref()
            .map(|previous| {
                previous
                    .columns
                    .iter()
                    .filter(|column| matches!(column.column_type, ColumnType::Vector(_)))
                    .map(|column| column.name.clone())
                    .collect::<HashSet<_>>()
            })
            .unwrap_or_default();
        let current_vector_columns = meta
            .columns
            .iter()
            .filter(|column| matches!(column.column_type, ColumnType::Vector(_)))
            .map(|column| column.name.clone())
            .collect::<HashSet<_>>();
        let vector_renames = ddl
            .iter()
            .filter_map(|change| {
                let DdlChange::AlterTable {
                    name: change_table,
                    constraints,
                    ..
                } = change
                else {
                    return None;
                };
                (change_table == name)
                    .then(|| read_vector_rename_constraint(constraints))
                    .flatten()
                    .filter(|(from, to)| {
                        previous_vector_columns.contains(from)
                            && current_vector_columns.contains(to)
                    })
            })
            .map(|(from, to)| {
                (
                    VectorIndexRef::new(name, from),
                    VectorIndexRef::new(name, to),
                )
            })
            .collect::<Vec<_>>();
        let renamed_from = vector_renames
            .iter()
            .map(|(from, _)| from.column.clone())
            .collect::<HashSet<_>>();
        let dropped_vector_columns = previous_vector_columns
            .difference(&current_vector_columns)
            .filter(|column| !renamed_from.contains(*column))
            .cloned()
            .collect::<HashSet<_>>();
        self.with_db(|db| {
            let write_txn = db.begin_write().map_err(Self::storage_error)?;
            let mut identity_mutations = content_identity::schema_mutations(name, meta)?;
            identity_mutations.extend(
                previous_rows
                    .iter()
                    .map(|row| content_identity::remove_row_mutation(name, row.row_id)),
            );
            let mut ordered_rows = rows.iter().collect::<Vec<_>>();
            ordered_rows.sort_by_key(|row| (row.lsn, row.created_tx));
            for row in ordered_rows {
                identity_mutations.push(content_identity::row_mutation(name, row, Some(meta))?);
            }
            for entry in &previous_vectors {
                let previous_quantization = previous_vector_quantization
                    .get(&entry.index)
                    .copied()
                    .unwrap_or_default();
                identity_mutations.push(content_identity::remove_vector_mutation(
                    &entry.index,
                    entry.row_id,
                    previous_quantization,
                ));
                identity_mutations.push(content_identity::remove_vector_version_mutation(
                    &entry.index,
                    entry.row_id,
                    entry.created_tx,
                    entry.lsn,
                    previous_quantization,
                ));
                if dropped_vector_columns.contains(&entry.index.column) {
                    continue;
                }
                let mut current = entry.clone();
                if let Some((_, to)) = vector_renames.iter().find(|(from, _)| from == &entry.index)
                {
                    current.index = to.clone();
                }
                if current_vector_columns.contains(&current.index.column) {
                    let quantization = vector_quantization
                        .get(&current.index)
                        .copied()
                        .unwrap_or_default();
                    identity_mutations
                        .push(content_identity::vector_mutation(&current, quantization));
                    identity_mutations.push(content_identity::vector_version_mutation(
                        &current,
                        quantization,
                    ));
                }
            }
            for (from, to) in &vector_renames {
                self.rename_vector_partition_generation_index_in_write(&write_txn, from, to)?;
            }
            if !dropped_vector_columns.is_empty() {
                self.remove_vector_partition_records_matching_all_in_write(
                    &write_txn,
                    &|index: &VectorIndexRef| {
                        index.table == name && dropped_vector_columns.contains(&index.column)
                    },
                )?;
            }
            self.rewrite_vector_entries_for_schema_in_write(
                &write_txn,
                name,
                &vector_renames,
                &dropped_vector_columns,
                &vector_quantization,
            )?;
            {
                let mut meta_table = write_txn
                    .open_table(META_TABLE)
                    .map_err(Self::storage_error)?;
                let key = Self::meta_key(name);
                let encoded = Self::encode(meta)?;
                meta_table
                    .insert(key.as_str(), encoded.as_slice())
                    .map_err(Self::storage_error)?;
            }
            {
                let table_name = Self::rel_table_name(name);
                let table_def: TableDefinition<&[u8], &[u8]> =
                    TableDefinition::new(table_name.as_str());
                let _ = write_txn.delete_table(table_def);
                let legacy_table_def: TableDefinition<u64, &[u8]> =
                    TableDefinition::new(table_name.as_str());
                let _ = write_txn.delete_table(legacy_table_def);
                let mut redb_table = write_txn
                    .open_table(table_def)
                    .map_err(Self::storage_error)?;
                for row in rows {
                    let encoded = Self::encode_versioned_row(row, Some(meta))?;
                    let key = Self::rel_row_key(row);
                    redb_table
                        .insert(key.as_slice(), encoded.as_slice())
                        .map_err(Self::storage_error)?;
                }
            }
            // An index this rewrite stops declaring is retired here, while the
            // declaration that wrote its postings is still the one they match.
            if let Some(previous_meta) = previous_meta.as_ref() {
                Self::retire_undeclared_relational_indexes_in_write(
                    &write_txn,
                    &self.path,
                    name,
                    previous_meta,
                    meta,
                    &mut self.proof_admission(),
                )?;
            }
            #[cfg(any(test, feature = "test-seams"))]
            table_meta_rewrite_checkpoint_for_test(1);
            // The ready marker is a promise about the exact committed image,
            // including an index with no rows. Rebuild its posting tables in
            // this schema-rewrite transaction before publishing that marker.
            Self::rebuild_relational_indexes_in_write(
                &write_txn,
                &self.path,
                name,
                meta,
                Some(rows),
                &mut self.proof_admission(),
            )?;
            #[cfg(any(test, feature = "test-seams"))]
            table_meta_rewrite_checkpoint_for_test(2);
            Self::retain_sync_source_provenance_for_table_rows(&write_txn, name, rows)?;
            let live_rows = rows
                .iter()
                .filter(|row| row.deleted_tx.is_none())
                .map(|row| row.row_id)
                .collect::<HashSet<_>>();
            identity_mutations.extend(
                sources
                    .keys()
                    .filter(|(table, row_id)| table == name && !live_rows.contains(row_id))
                    .map(|(table, row_id)| {
                        content_identity::remove_sync_source_mutation(table, *row_id)
                    }),
            );
            {
                let mut config_table = write_txn
                    .open_table(CONFIG_TABLE)
                    .map_err(Self::storage_error)?;
                for (key, encoded) in config_values {
                    Self::update_policy_hold_release_index(&write_txn, key, true)?;
                    config_table
                        .insert(key, encoded.as_slice())
                        .map_err(Self::storage_error)?;
                    identity_mutations
                        .extend(content_identity::config_mutations(key, Some(&encoded)));
                }
            }
            {
                let mut ddl_table = write_txn
                    .open_table(DDL_LOG_TABLE)
                    .map_err(Self::storage_error)?;
                for (index, change) in ddl.iter().enumerate() {
                    let key = Self::ddl_log_key_for_index(lsn, index, ddl.len());
                    let encoded = Self::encode(change)?;
                    ddl_table
                        .insert(key.as_str(), encoded.as_slice())
                        .map_err(Self::storage_error)?;
                    identity_mutations
                        .push(content_identity::encoded_history_mutation(&key, change)?);
                }
            }
            Self::apply_content_identity_mutations_in_write(
                &write_txn,
                &identity_mutations,
                &mut self.proof_admission(),
            )?;
            write_txn.commit().map_err(Self::storage_error)?;
            #[cfg(any(test, feature = "test-seams"))]
            table_meta_rewrite_checkpoint_for_test(3);
            Ok(())
        })
    }

    pub fn rewrite_graph_edges(&self, edges: &[AdjEntry]) -> Result<()> {
        self.with_db(|db| {
            let write_txn = db.begin_write().map_err(Self::storage_error)?;
            let _ = write_txn.delete_table(GRAPH_FWD_TABLE);
            let _ = write_txn.delete_table(GRAPH_REV_TABLE);
            {
                let mut fwd_table = write_txn
                    .open_table(GRAPH_FWD_TABLE)
                    .map_err(Self::storage_error)?;
                let mut rev_table = write_txn
                    .open_table(GRAPH_REV_TABLE)
                    .map_err(Self::storage_error)?;

                for entry in edges {
                    let encoded = Self::encode(entry)?;
                    let fwd_key = Self::graph_fwd_key(entry);
                    let rev_key = Self::graph_rev_key(entry);
                    fwd_table
                        .insert(fwd_key.as_slice(), encoded.as_slice())
                        .map_err(Self::storage_error)?;
                    rev_table
                        .insert(rev_key.as_slice(), encoded.as_slice())
                        .map_err(Self::storage_error)?;
                }
            }
            Self::reset_content_identity_families_in_write(
                &write_txn,
                &[content_identity::LogicalFamily::Graph],
                &mut self.proof_admission(),
            )?;
            let mut ordered = edges.iter().collect::<Vec<_>>();
            ordered.sort_by_key(|edge| (edge.lsn, edge.created_tx));
            let mutations = ordered
                .into_iter()
                .map(content_identity::edge_mutation)
                .collect::<Result<Vec<_>>>()?;
            Self::apply_content_identity_mutations_in_write(
                &write_txn,
                &mutations,
                &mut self.proof_admission(),
            )?;
            write_txn.commit().map_err(Self::storage_error)?;
            Ok(())
        })
    }

    /// How many distinct prefix values this store currently holds a maintained
    /// count for, over exactly these columns. Inspection only: it counts
    /// records, never rows.
    pub(crate) fn stored_maintained_count_values(
        &self,
        table: &str,
        columns: &[(String, contextdb_core::SortDirection)],
    ) -> Result<u64> {
        self.with_db(|db| {
            let read_txn = db.begin_read().map_err(Self::storage_error)?;
            let counts = match read_txn.open_table(RELATIONAL_INDEX_COUNT_TABLE) {
                Ok(counts) => counts,
                Err(redb::TableError::TableDoesNotExist(_)) => return Ok(0),
                Err(error) => return Err(Self::storage_error(error)),
            };
            let mut stored = 0u64;
            for entry in counts.iter().map_err(Self::storage_error)? {
                let (key, _) = entry.map_err(Self::storage_error)?;
                let decoded: EncodedRelationalIndexCountKey = Self::decode(key.value())?;
                if decoded.table == table && decoded.columns == columns {
                    stored = stored.saturating_add(1);
                }
            }
            Ok(stored)
        })
    }

    pub fn load_all_table_meta(&self) -> Result<HashMap<String, TableMeta>> {
        self.with_db(|db| {
            let read_txn = db.begin_read().map_err(Self::storage_error)?;
            let meta_table = match read_txn.open_table(META_TABLE) {
                Ok(table) => table,
                Err(redb::TableError::TableDoesNotExist(_)) => return Ok(HashMap::new()),
                Err(err) => return Err(Self::storage_error(err)),
            };

            let mut tables = HashMap::new();
            for entry in meta_table.iter().map_err(Self::storage_error)? {
                let (key, value) = entry.map_err(Self::storage_error)?;
                let key = key.value();
                if let Some(name) = key.strip_prefix("table:") {
                    let (meta, via_legacy) = Self::decode_table_meta_versioned(value.value())?;
                    if via_legacy {
                        self.used_legacy_table_meta_layout
                            .store(true, Ordering::Relaxed);
                    }
                    tables.insert(name.to_string(), meta);
                }
            }
            Ok(tables)
        })
    }

    /// Every config value whose key starts with `prefix`, decoded, in key order.
    /// The config keys are sorted, so a range from `prefix` and a stop at the
    /// first key that no longer shares it collects exactly the contiguous run.
    pub fn load_config_values_with_prefix<T: serde::de::DeserializeOwned>(
        &self,
        prefix: &str,
    ) -> Result<Vec<(String, T)>> {
        self.with_db(|db| {
            let read_txn = db.begin_read().map_err(Self::storage_error)?;
            let config_table = match read_txn.open_table(CONFIG_TABLE) {
                Ok(table) => table,
                Err(redb::TableError::TableDoesNotExist(_)) => return Ok(Vec::new()),
                Err(err) => return Err(Self::storage_error(err)),
            };
            let mut out = Vec::new();
            for entry in config_table.range(prefix..).map_err(Self::storage_error)? {
                let (key, value) = entry.map_err(Self::storage_error)?;
                let key = key.value();
                if !key.starts_with(prefix) {
                    break;
                }
                out.push((key.to_string(), Self::decode(value.value())?));
            }
            Ok(out)
        })
    }

    /// Decode only the requested page. The extra key is inspected solely to
    /// report a continuation; its value is never copied or decoded.
    pub(crate) fn load_config_page_with_prefix<T: serde::de::DeserializeOwned>(
        &self,
        prefix: &str,
        cursor: Option<&str>,
        limit: usize,
        accountant: Arc<crate::memory_accounting::MemoryAccountant>,
    ) -> Result<(Vec<(String, T)>, bool)> {
        self.with_db(|db| {
            let read_txn = db.begin_read().map_err(Self::storage_error)?;
            let config_table = match read_txn.open_table(CONFIG_TABLE) {
                Ok(table) => table,
                Err(redb::TableError::TableDoesNotExist(_)) => return Ok((Vec::new(), false)),
                Err(error) => return Err(Self::storage_error(error)),
            };
            let memory = crate::read_image_memory::ImageMemory::charging_for(
                accountant,
                "sync_policy",
                "read_refused_outcome_page",
                "Reduce the page size or raise MEMORY_LIMIT before reading refusal outcomes.",
            );
            let mut page = Vec::new();
            let mut more = false;
            for entry in config_table
                .range(cursor.unwrap_or(prefix)..)
                .map_err(Self::storage_error)?
            {
                let (key, value) = entry.map_err(Self::storage_error)?;
                let key = key.value();
                if !key.starts_with(prefix) {
                    break;
                }
                if cursor.is_some_and(|cursor| key <= cursor) {
                    continue;
                }
                if page.len() == limit {
                    more = true;
                    break;
                }
                let bytes = value.value();
                memory.reserve(key.len().saturating_add(bytes.len()))?;
                let decoded = memory.scope(|| Self::decode(bytes))?;
                page.push((key.to_owned(), decoded));
            }
            Ok((page, more))
        })
    }

    /// Inspect a peer-scoped run one value at a time and retain only the next
    /// source-order candidate. The digest suffix on durable keys has no source
    /// ordering, so selecting one candidate requires a scan of that peer's run.
    pub(crate) fn load_next_config_value_by_source<T, F>(
        &self,
        prefix: &str,
        after: Option<(u64, &str)>,
        accountant: Arc<crate::memory_accounting::MemoryAccountant>,
        source_lsn: F,
    ) -> Result<Option<(String, T, Arc<crate::read_image_memory::ImageMemory>)>>
    where
        T: serde::de::DeserializeOwned,
        F: Fn(&T) -> Option<u64>,
    {
        self.with_db(|db| {
            let read_txn = db.begin_read().map_err(Self::storage_error)?;
            let config_table = match read_txn.open_table(CONFIG_TABLE) {
                Ok(table) => table,
                Err(redb::TableError::TableDoesNotExist(_)) => return Ok(None),
                Err(error) => return Err(Self::storage_error(error)),
            };
            let mut candidate: Option<(String, T, Arc<crate::read_image_memory::ImageMemory>)> =
                None;
            for entry in config_table.range(prefix..).map_err(Self::storage_error)? {
                let (key, value) = entry.map_err(Self::storage_error)?;
                let key = key.value();
                if !key.starts_with(prefix) {
                    break;
                }
                let memory = crate::read_image_memory::ImageMemory::charging_for(
                    Arc::clone(&accountant),
                    "sync_policy",
                    "read_held_replay",
                    "Raise MEMORY_LIMIT before replaying this held data unit.",
                );
                let bytes = value.value();
                memory.reserve(key.len().saturating_add(bytes.len()))?;
                let decoded: T = memory.scope(|| Self::decode(bytes))?;
                let Some(position) = source_lsn(&decoded) else {
                    continue;
                };
                if after.is_some_and(|after| (position, key) <= after) {
                    continue;
                }
                if candidate.as_ref().is_some_and(|(best_key, best, _)| {
                    (position, key)
                        >= (
                            source_lsn(best).expect("selected peer value has a source position"),
                            best_key.as_str(),
                        )
                }) {
                    continue;
                }
                candidate = Some((key.to_owned(), decoded, memory));
            }
            Ok(candidate)
        })
    }

    /// Every raw config value whose key starts with `prefix`, in key order.
    /// Callers that treat the stored bytes as an authority boundary can apply
    /// their own exact decoder without broadening generic config compatibility.
    pub(crate) fn load_config_values_raw_with_prefix(
        &self,
        prefix: &str,
    ) -> Result<Vec<(String, Vec<u8>)>> {
        self.with_db(|db| {
            let read_txn = db.begin_read().map_err(Self::storage_error)?;
            let config_table = match read_txn.open_table(CONFIG_TABLE) {
                Ok(table) => table,
                Err(redb::TableError::TableDoesNotExist(_)) => return Ok(Vec::new()),
                Err(err) => return Err(Self::storage_error(err)),
            };
            let mut out = Vec::new();
            for entry in config_table.range(prefix..).map_err(Self::storage_error)? {
                let (key, value) = entry.map_err(Self::storage_error)?;
                let key = key.value();
                if !key.starts_with(prefix) {
                    break;
                }
                out.push((key.to_string(), value.value().to_vec()));
            }
            Ok(out)
        })
    }

    /// The raw config value for exactly `key`, if present.
    pub(crate) fn load_config_value_raw(&self, key: &str) -> Result<Option<Vec<u8>>> {
        self.with_db(|db| {
            let read_txn = db.begin_read().map_err(Self::storage_error)?;
            let config_table = match read_txn.open_table(CONFIG_TABLE) {
                Ok(table) => table,
                Err(redb::TableError::TableDoesNotExist(_)) => return Ok(None),
                Err(err) => return Err(Self::storage_error(err)),
            };
            Ok(config_table
                .get(key)
                .map_err(Self::storage_error)?
                .map(|value| value.value().to_vec()))
        })
    }

    pub(crate) fn config_value_exists(&self, key: &str) -> Result<bool> {
        self.with_db(|db| {
            let txn = db.begin_read().map_err(Self::storage_error)?;
            let table = match txn.open_table(if policy_hold_index_key(key) {
                POLICY_HOLD_INDEX_TABLE
            } else {
                CONFIG_TABLE
            }) {
                Ok(table) => table,
                Err(redb::TableError::TableDoesNotExist(_)) => return Ok(false),
                Err(error) => return Err(Self::storage_error(error)),
            };
            Ok(table.get(key).map_err(Self::storage_error)?.is_some())
        })
    }

    /// Policy-hold indexing enumerates keys without decoding unrelated values;
    /// the caller saves its cursor alongside each indexed record before advancing.
    pub(crate) fn next_config_key(
        &self,
        prefix: &str,
        after: Option<&str>,
        memory: &Arc<crate::read_image_memory::ImageMemory>,
    ) -> Result<Option<String>> {
        self.with_db(|db| {
            let txn = db.begin_read().map_err(Self::storage_error)?;
            let table = match txn.open_table(CONFIG_TABLE) {
                Ok(table) => table,
                Err(redb::TableError::TableDoesNotExist(_)) => return Ok(None),
                Err(error) => return Err(Self::storage_error(error)),
            };
            for entry in table
                .range(after.unwrap_or(prefix)..)
                .map_err(Self::storage_error)?
            {
                let (key, _) = entry.map_err(Self::storage_error)?;
                let key = key.value();
                if !key.starts_with(prefix) {
                    break;
                }
                if after.is_some_and(|after| key <= after) {
                    continue;
                }
                memory.reserve(key.len())?;
                return Ok(Some(key.to_owned()));
            }
            Ok(None)
        })
    }

    /// The borrowed encoded value is admitted before the decoder can allocate.
    /// The caller retains the lease for as long as it keeps the decoded record.
    pub(crate) fn load_config_value_admitted<T: serde::de::DeserializeOwned>(
        &self,
        key: &str,
        memory: &Arc<crate::read_image_memory::ImageMemory>,
    ) -> Result<Option<T>> {
        self.with_db(|db| {
            let txn = db.begin_read().map_err(Self::storage_error)?;
            let table = match txn.open_table(if policy_hold_index_key(key) {
                POLICY_HOLD_INDEX_TABLE
            } else {
                CONFIG_TABLE
            }) {
                Ok(table) => table,
                Err(redb::TableError::TableDoesNotExist(_)) => return Ok(None),
                Err(error) => return Err(Self::storage_error(error)),
            };
            let Some(value) = table.get(key).map_err(Self::storage_error)? else {
                return Ok(None);
            };
            memory.reserve(value.value().len())?;
            memory.scope(|| Self::decode(value.value())).map(Some)
        })
    }

    /// Point-read one bounded set of config keys in request order. Each
    /// borrowed value is admitted before either decoding or making an owned
    /// copy; unrelated values in the table are never visited.
    pub(crate) fn load_config_values_for_keys_admitted<T: serde::de::DeserializeOwned>(
        &self,
        keys: &[String],
        memory: &Arc<crate::read_image_memory::ImageMemory>,
    ) -> Result<Vec<T>> {
        self.with_db(|db| {
            let txn = db.begin_read().map_err(Self::storage_error)?;
            let table = match txn.open_table(CONFIG_TABLE) {
                Ok(table) => table,
                Err(redb::TableError::TableDoesNotExist(_)) => return Ok(Vec::new()),
                Err(error) => return Err(Self::storage_error(error)),
            };
            let mut values = Vec::new();
            for key in keys {
                let Some(value) = table.get(key.as_str()).map_err(Self::storage_error)? else {
                    continue;
                };
                memory.reserve(value.value().len())?;
                values.push(memory.scope(|| Self::decode(value.value()))?);
            }
            Ok(values)
        })
    }

    /// Selection indexes contain physical primary keys. Scan only the requested
    /// scoped runs, then point-read those primary records under one retained lease.
    pub(crate) fn load_indexed_config_values<T: serde::de::DeserializeOwned>(
        &self,
        mut keys: BTreeSet<String>,
        prefixes: &[String],
        memory: &Arc<crate::read_image_memory::ImageMemory>,
    ) -> Result<Vec<(String, T)>> {
        self.with_db(|db| {
            let txn = db.begin_read().map_err(Self::storage_error)?;
            let table = match txn.open_table(CONFIG_TABLE) {
                Ok(table) => table,
                Err(redb::TableError::TableDoesNotExist(_)) => return Ok(Vec::new()),
                Err(error) => return Err(Self::storage_error(error)),
            };
            let indexes = match txn.open_table(POLICY_HOLD_INDEX_TABLE) {
                Ok(table) => Some(table),
                Err(redb::TableError::TableDoesNotExist(_)) => None,
                Err(error) => return Err(Self::storage_error(error)),
            };
            for prefix in prefixes {
                let Some(indexes) = &indexes else {
                    break;
                };
                for entry in indexes
                    .range(prefix.as_str()..)
                    .map_err(Self::storage_error)?
                {
                    let (key, value) = entry.map_err(Self::storage_error)?;
                    if !key.value().starts_with(prefix) {
                        break;
                    }
                    memory.reserve(value.value().len().saturating_add(128))?;
                    let primary: String = memory.scope(|| Self::decode(value.value()))?;
                    keys.insert(primary);
                }
            }
            let mut values = Vec::new();
            for key in keys {
                let Some(value) = table.get(key.as_str()).map_err(Self::storage_error)? else {
                    continue;
                };
                memory.reserve(value.value().len().saturating_add(key.len()))?;
                let decoded = memory.scope(|| Self::decode(value.value()))?;
                values.push((key, decoded));
            }
            Ok(values)
        })
    }

    pub fn load_config_value<T: serde::de::DeserializeOwned>(
        &self,
        key: &str,
    ) -> Result<Option<T>> {
        self.with_db(|db| {
            let read_txn = db.begin_read().map_err(Self::storage_error)?;
            let config_table = match read_txn.open_table(CONFIG_TABLE) {
                Ok(table) => table,
                Err(redb::TableError::TableDoesNotExist(_)) => return Ok(None),
                Err(err) => return Err(Self::storage_error(err)),
            };
            let value = match config_table.get(key).map_err(Self::storage_error)? {
                Some(value) => Some(Self::decode(value.value())?),
                None => None,
            };
            Ok(value)
        })
    }

    fn decode_relational_source_row(
        table: &str,
        meta: &TableMeta,
        bytes: &[u8],
    ) -> Result<VersionedRow> {
        contextdb_core::find_attribution::count("decoded_rows", 1);
        #[cfg(feature = "test-seams")]
        {
            crate::read_work_probe::note_decoded_row();
            crate::read_work_probe::note_stored_row_bytes(bytes.len());
        }
        let row = Self::decode_versioned_row(bytes, Some(meta))?;
        validate_read_row(table, &row, meta).map_err(|error| Error::StoreCorrupted {
            path: table.to_owned(),
            reason: error.to_string(),
        })?;
        Ok(row)
    }

    fn relational_row_by_id_in_read(
        database_path: &Path,
        root_kind: &str,
        read: &redb::ReadTransaction,
        table: &str,
        meta: &TableMeta,
        row_id: RowId,
        snapshot: SnapshotId,
    ) -> Result<Option<VersionedRow>> {
        let name = Self::rel_table_name(table);
        let definition: TableDefinition<&[u8], &[u8]> = TableDefinition::new(name.as_str());
        let relation = match read.open_table(definition) {
            Ok(table) => table,
            Err(redb::TableError::TableDoesNotExist(_)) => {
                return Err(Error::StoreCorrupted {
                    path: database_path.display().to_string(),
                    reason: format!("relational table {table} is absent from the {root_kind} root"),
                });
            }
            Err(error) => return Err(Self::storage_error(error)),
        };
        let (lower, upper) = Self::rel_row_key_range(row_id);
        let mut versions = relation
            .range(lower.as_slice()..upper.as_slice())
            .map_err(Self::storage_error)?;
        while let Some(entry) = versions.next_back() {
            let (key, value) = entry.map_err(Self::storage_error)?;
            let row = Self::decode_relational_source_row(table, meta, value.value())?;
            if Self::rel_row_key_from_parts(row.row_id, row.created_tx, row.lsn) != key.value() {
                return Err(Error::StoreCorrupted {
                    path: database_path.display().to_string(),
                    reason: format!(
                        "relational table {table} row body disagrees with its saved version key"
                    ),
                });
            }
            if row.created_tx.0 <= snapshot.0
                && row.deleted_tx.is_none_or(|deleted| deleted.0 > snapshot.0)
            {
                return Ok(Some(row));
            }
        }
        Ok(None)
    }

    /// Resolve the one durable relational version named by a vector
    /// membership without walking any other row identity. The relation key
    /// carries the LSN, so unrelated versions can be rejected before their
    /// bodies are decoded.
    fn relational_row_by_id_lsn_in_read(
        database_path: &Path,
        root_kind: &str,
        read: &redb::ReadTransaction,
        table: &str,
        meta: &TableMeta,
        row_id: RowId,
        lsn: Lsn,
    ) -> Result<Option<VersionedRow>> {
        let name = Self::rel_table_name(table);
        let definition: TableDefinition<&[u8], &[u8]> = TableDefinition::new(name.as_str());
        let relation = match read.open_table(definition) {
            Ok(table) => table,
            Err(redb::TableError::TableDoesNotExist(_)) => {
                return Err(Error::StoreCorrupted {
                    path: database_path.display().to_string(),
                    reason: format!("relational table {table} is absent from the {root_kind} root"),
                });
            }
            Err(error) => return Err(Self::storage_error(error)),
        };
        let (lower, upper) = Self::rel_row_key_range(row_id);
        for entry in relation
            .range(lower.as_slice()..upper.as_slice())
            .map_err(Self::storage_error)?
        {
            let (key, value) = entry.map_err(Self::storage_error)?;
            let encoded_key = key.value();
            if encoded_key.len() != 24 {
                return Err(Error::StoreCorrupted {
                    path: database_path.display().to_string(),
                    reason: format!("relational table {table} contains a malformed row key"),
                });
            }
            let key_lsn = u64::from_be_bytes(
                encoded_key[16..24]
                    .try_into()
                    .expect("validated relational key width"),
            );
            if key_lsn != lsn.0 {
                continue;
            }
            let row = Self::decode_relational_source_row(table, meta, value.value())?;
            if row.row_id != row_id
                || row.lsn != lsn
                || Self::rel_row_key_from_parts(row.row_id, row.created_tx, row.lsn) != encoded_key
            {
                return Err(Error::StoreCorrupted {
                    path: database_path.display().to_string(),
                    reason: format!(
                        "relational table {table} row body disagrees with its point identity"
                    ),
                });
            }
            return Ok(Some(row));
        }
        Ok(None)
    }

    /// Decode one durable row version through the writable store's ordinary
    /// read transaction. This is the point-read half of writable row paging:
    /// callers supply the MVCC snapshot, and later commits remain invisible.
    pub(crate) fn load_relational_row_by_id_at(
        &self,
        table: &str,
        meta: &TableMeta,
        row_id: RowId,
        snapshot: SnapshotId,
    ) -> Result<Option<VersionedRow>> {
        #[cfg(feature = "test-seams")]
        crate::read_work_probe::note_row_version_range_read();
        self.with_db(|db| {
            let read = db.begin_read().map_err(Self::storage_error)?;
            Self::relational_row_by_id_in_read(
                self.path(),
                "durable",
                &read,
                table,
                meta,
                row_id,
                snapshot,
            )
        })
    }

    pub(crate) fn load_relational_row_by_id_lsn(
        &self,
        table: &str,
        meta: &TableMeta,
        row_id: RowId,
        lsn: Lsn,
    ) -> Result<Option<VersionedRow>> {
        self.with_db(|db| {
            let read = db.begin_read().map_err(Self::storage_error)?;
            Self::relational_row_by_id_lsn_in_read(
                self.path(),
                "durable",
                &read,
                table,
                meta,
                row_id,
                lsn,
            )
        })
    }

    /// The stored byte length of each named row version, keyed as it was
    /// asked for. A key the store does not hold is absent from the answer.
    ///
    /// This is what a version physically occupies, which is not what it
    /// occupies in memory: a committed body the in-memory directory has shed
    /// still takes its full room in the file, and a reclaim or size answer
    /// that described only the resident projection would stop scaling with
    /// what was actually stored.
    pub(crate) fn stored_relational_row_bytes(
        &self,
        keys: &[(String, RowId, TxId, Lsn)],
    ) -> Result<HashMap<(String, RowId, TxId, Lsn), usize>> {
        if keys.is_empty() {
            return Ok(HashMap::new());
        }
        #[cfg(test)]
        if STORED_ROW_BYTES_FAULT.with(|armed| armed.replace(false)) {
            return Err(Error::Other(
                "injected stored relational row size read failure".to_string(),
            ));
        }
        self.with_db(|db| {
            let mut answer = HashMap::new();
            let read = db.begin_read().map_err(Self::storage_error)?;
            let mut opened: HashMap<&str, Option<redb::ReadOnlyTable<&[u8], &[u8]>>> =
                HashMap::new();
            for (table, row_id, created_tx, lsn) in keys {
                let relation = match opened.entry(table.as_str()) {
                    std::collections::hash_map::Entry::Occupied(entry) => entry.into_mut(),
                    std::collections::hash_map::Entry::Vacant(entry) => {
                        let name = Self::rel_table_name(table);
                        let definition: TableDefinition<&[u8], &[u8]> =
                            TableDefinition::new(name.as_str());
                        let opened = match read.open_table(definition) {
                            Ok(relation) => Some(relation),
                            Err(redb::TableError::TableDoesNotExist(_)) => None,
                            Err(error) => return Err(Self::storage_error(error)),
                        };
                        entry.insert(opened)
                    }
                };
                let Some(relation) = relation.as_ref() else {
                    continue;
                };
                let key = Self::rel_row_key_from_parts(*row_id, *created_tx, *lsn);
                let Some(stored) = relation.get(key.as_slice()).map_err(Self::storage_error)?
                else {
                    continue;
                };
                // A borrowed slice into the page redb already holds: reading
                // its length copies nothing.
                let bytes = stored.value().len();
                answer.insert((table.clone(), *row_id, *created_tx, *lsn), bytes);
            }
            Ok(answer)
        })
    }

    /// Load one exact durable row version for a physical MVCC scan.  Point
    /// lookup resolves by snapshot; a physical cursor already names the
    /// version and must not turn two retained versions into two copies of the
    /// newest body.
    pub(crate) fn load_relational_row_version(
        &self,
        table: &str,
        meta: &TableMeta,
        row_id: RowId,
        created_tx: TxId,
        lsn: Lsn,
    ) -> Result<Option<VersionedRow>> {
        #[cfg(feature = "test-seams")]
        crate::read_work_probe::note_row_version_point_read();
        self.with_db(|db| {
            let read = db.begin_read().map_err(Self::storage_error)?;
            let name = Self::rel_table_name(table);
            let definition: TableDefinition<&[u8], &[u8]> = TableDefinition::new(name.as_str());
            let relation = match read.open_table(definition) {
                Ok(relation) => relation,
                Err(redb::TableError::TableDoesNotExist(_)) => return Ok(None),
                Err(error) => return Err(Self::storage_error(error)),
            };
            let key = Self::rel_row_key_from_parts(row_id, created_tx, lsn);
            let Some(value) = relation.get(key.as_slice()).map_err(Self::storage_error)? else {
                return Ok(None);
            };
            let row = Self::decode_relational_source_row(table, meta, value.value())?;
            if row.row_id != row_id || row.created_tx != created_tx || row.lsn != lsn {
                return Err(Error::StoreCorrupted {
                    path: self.path().display().to_string(),
                    reason: format!(
                        "relational table {table} row body disagrees with its saved version key"
                    ),
                });
            }
            Ok(Some(row))
        })
    }

    #[cfg(feature = "test-seams")]
    pub(crate) fn damage_first_saved_row_for_test(
        &self,
        table: &str,
        swap_body: bool,
    ) -> Result<()> {
        self.with_db(|db| {
            let write = db.begin_write().map_err(Self::storage_error)?;
            let name = Self::rel_table_name(table);
            let definition: TableDefinition<&[u8], &[u8]> = TableDefinition::new(name.as_str());
            {
                let mut relation = write.open_table(definition).map_err(Self::storage_error)?;
                let rows = relation
                    .iter()
                    .map_err(Self::storage_error)?
                    .take(2)
                    .map(|entry| {
                        entry
                            .map(|(key, value)| (key.value().to_vec(), value.value().to_vec()))
                            .map_err(Self::storage_error)
                    })
                    .collect::<Result<Vec<_>>>()?;
                if rows.len() != 2 {
                    return Err(Error::Other(
                        "saved-row damage fixture requires two versions".to_owned(),
                    ));
                }
                if swap_body {
                    relation
                        .insert(rows[0].0.as_slice(), rows[1].1.as_slice())
                        .map_err(Self::storage_error)?;
                } else {
                    relation
                        .remove(rows[0].0.as_slice())
                        .map_err(Self::storage_error)?;
                }
            }
            write.commit().map_err(Self::storage_error)
        })
    }

    pub fn load_relational_table(&self, name: &str) -> Result<Vec<VersionedRow>> {
        self.with_db(|db| {
            let read_txn = db.begin_read().map_err(Self::storage_error)?;
            let table_meta = Self::load_table_meta_in_read_txn(&read_txn, name)?;
            let table_name = Self::rel_table_name(name);
            let table_def: TableDefinition<&[u8], &[u8]> =
                TableDefinition::new(table_name.as_str());
            match read_txn.open_table(table_def) {
                Ok(table) => {
                    let mut rows = Vec::new();
                    for entry in table.iter().map_err(Self::storage_error)? {
                        let (_, value) = entry.map_err(Self::storage_error)?;
                        rows.push(Self::decode_versioned_row(
                            value.value(),
                            table_meta.as_ref(),
                        )?);
                    }
                    Ok(rows)
                }
                Err(redb::TableError::TableDoesNotExist(_)) => Ok(Vec::new()),
                Err(redb::TableError::TableTypeMismatch { .. }) => {
                    Err(Self::unrecognized_relational_layout(name))
                }
                Err(err) => Err(Self::storage_error(err)),
            }
        })
    }

    /// A relational table with an incompatible versioned-key shape is refused
    /// with the typed format error before its rows are read.
    fn unrecognized_relational_layout(name: &str) -> Error {
        Error::LegacyVectorStoreDetected {
            found_format_marker: format!("{name} uses an unrecognized relational key layout"),
            expected_release: CURRENT_FORMAT_VERSION.to_owned(),
        }
    }

    /// Decode a table one row at a time.  Writable open uses this path so a
    /// database larger than RAM never exists as a temporary `Vec` before its
    /// lightweight row and index directories are built.
    pub(crate) fn visit_relational_table(
        &self,
        name: &str,
        visit: impl FnMut(VersionedRow) -> Result<()>,
    ) -> Result<()> {
        self.visit_relational_table_impl(name, None, visit)
    }

    /// Charge one persisted row's decoded allocations before each allocation
    /// occurs. The transient charge remains held through the caller's row
    /// insertion and is released before the next stored row is decoded.
    pub(crate) fn visit_relational_table_with_admission(
        &self,
        name: &str,
        accountant: &Arc<crate::memory_accounting::MemoryAccountant>,
        visit: impl FnMut(VersionedRow) -> Result<()>,
    ) -> Result<()> {
        self.visit_relational_table_impl(name, Some(accountant), visit)
    }

    fn visit_relational_table_impl(
        &self,
        name: &str,
        accountant: Option<&Arc<crate::memory_accounting::MemoryAccountant>>,
        mut visit: impl FnMut(VersionedRow) -> Result<()>,
    ) -> Result<()> {
        let page_memory = accountant.map(|accountant| {
            crate::read_image_memory::ImageMemory::charging_for(
                Arc::clone(accountant),
                "sync",
                "stage_received_unit_row_image",
                "Raise MEMORY_LIMIT to admit the affected stored row before decoding it.",
            )
        });
        let page_failure = Arc::new(parking_lot::Mutex::new(None));
        let admission = page_memory.as_ref().map(|memory| {
            let memory = Arc::clone(memory);
            let failure = Arc::clone(&page_failure);
            Arc::new(move |bytes: usize| {
                memory.reserve(bytes).map_err(|error| {
                    *failure.lock() = Some(error);
                    std::io::Error::from(std::io::ErrorKind::OutOfMemory)
                })
            }) as Arc<dyn Fn(usize) -> std::io::Result<()> + Send + Sync>
        });
        let mut read = || {
            self.with_db(|db| {
            let read_txn = db.begin_read().map_err(Self::storage_error)?;
            let table_meta = Self::load_table_meta_in_read_txn(&read_txn, name)?;
            let table_name = Self::rel_table_name(name);
            let table_def: TableDefinition<&[u8], &[u8]> =
                TableDefinition::new(table_name.as_str());
            match read_txn.open_table(table_def) {
                Ok(table) => {
                    for entry in table.iter().map_err(Self::storage_error)? {
                        let (_, value) = entry.map_err(Self::storage_error)?;
                        let decoded = accountant.map(|accountant| {
                            crate::read_image_memory::ImageMemory::charging_for(
                                Arc::clone(accountant),
                                "sync",
                                "stage_received_unit_row_image",
                                "Raise MEMORY_LIMIT to admit the affected stored row before decoding it.",
                            )
                        });
                        if let Some(decoded) = decoded.as_ref() {
                            decoded.reserve(value.value().len())?;
                        }
                        let row = match decoded.as_ref() {
                            Some(decoded) => decoded.scope(|| {
                                Self::decode_versioned_row(value.value(), table_meta.as_ref())
                            }),
                            None => Self::decode_versioned_row(value.value(), table_meta.as_ref()),
                        }?;
                        visit(row)?;
                    }
                    Ok(())
                }
                Err(redb::TableError::TableDoesNotExist(_)) => Ok(()),
                Err(redb::TableError::TableTypeMismatch { .. }) => {
                    Err(Self::unrecognized_relational_layout(name))
                }
                Err(err) => Err(Self::storage_error(err)),
            }
        })
        };
        let result = match admission {
            Some(admission) => redb::with_read_memory_admission(admission, read),
            None => read(),
        };
        if let Some(error) = page_failure.lock().take() {
            return Err(error);
        }
        result
    }

    pub fn load_all_tables(&self) -> Result<HashMap<String, Vec<VersionedRow>>> {
        let mut all_tables = HashMap::new();
        for name in self.load_all_table_meta()?.into_keys() {
            let rows = self.load_relational_table(&name)?;
            all_tables.insert(name, rows);
        }
        Ok(all_tables)
    }

    pub fn load_forward_edges(&self) -> Result<Vec<AdjEntry>> {
        self.load_graph_table(GRAPH_FWD_TABLE)
    }

    pub fn load_reverse_edges(&self) -> Result<Vec<AdjEntry>> {
        self.load_graph_table(GRAPH_REV_TABLE)
    }

    pub fn load_vectors(&self) -> Result<Vec<VectorEntry>> {
        self.with_db(|db| {
            let read_txn = db.begin_read().map_err(Self::storage_error)?;
            let table = match read_txn.open_table(VECTORS_TABLE) {
                Ok(table) => table,
                Err(redb::TableError::TableDoesNotExist(_)) => return Ok(Vec::new()),
                Err(err) => return Err(Self::storage_error(err)),
            };

            let mut vectors = Vec::new();
            for entry in table.iter().map_err(Self::storage_error)? {
                let (_, value) = entry.map_err(Self::storage_error)?;
                vectors.push(Self::decode_vector_entry(value.value())?);
            }
            Ok(vectors)
        })
    }

    fn load_vector_partition_table_in_read<T: serde::de::DeserializeOwned>(
        &self,
        read_txn: &redb::ReadTransaction,
        definition: TableDefinition<&'static [u8], &'static [u8]>,
        kind: VectorPartitionRecordKind,
        expected_key: impl Fn(&T) -> Vec<u8>,
        prefix: Option<&[u8]>,
    ) -> Result<Vec<T>> {
        let table = match read_txn.open_byte_table_bounded(definition) {
            Ok(table) => table,
            Err(redb::TableError::TableDoesNotExist(_)) => return Ok(Vec::new()),
            Err(error) => return Err(Self::storage_error(error)),
        };
        let mut records = Vec::new();
        if let Some(prefix) = prefix {
            for entry in table.prefix_bounded(prefix).map_err(Self::storage_error)? {
                let (key, value) = entry.map_err(Self::storage_error)?;
                if !key.value().starts_with(prefix) {
                    break;
                }
                #[cfg(any(test, feature = "test-seams"))]
                if kind == VectorPartitionRecordKind::Membership {
                    VECTOR_MEMBERSHIP_RECORDS_DECODED
                        .with(|count| count.set(count.get().saturating_add(1)));
                }
                let record = self.decode_vector_partition_record(kind, value.value())?;
                if expected_key(&record).as_slice() != key.value() {
                    return Err(self.vector_partition_corruption(
                        "table key does not match its checksummed payload",
                    ));
                }
                records.push(record);
            }
        } else {
            for entry in table.iter().map_err(Self::storage_error)? {
                let (key, value) = entry.map_err(Self::storage_error)?;
                #[cfg(any(test, feature = "test-seams"))]
                if kind == VectorPartitionRecordKind::Membership {
                    VECTOR_MEMBERSHIP_RECORDS_DECODED
                        .with(|count| count.set(count.get().saturating_add(1)));
                }
                let record = self.decode_vector_partition_record(kind, value.value())?;
                if expected_key(&record).as_slice() != key.value() {
                    return Err(self.vector_partition_corruption(
                        "table key does not match its checksummed payload",
                    ));
                }
                records.push(record);
            }
        }
        Ok(records)
    }

    #[cfg(any(test, feature = "test-seams"))]
    pub(crate) fn reset_vector_membership_records_decoded_for_test() {
        VECTOR_MEMBERSHIP_RECORDS_DECODED.with(|count| count.set(0));
    }

    #[cfg(any(test, feature = "test-seams"))]
    pub(crate) fn vector_membership_records_decoded_for_test() -> u64 {
        VECTOR_MEMBERSHIP_RECORDS_DECODED.with(std::cell::Cell::get)
    }

    #[cfg(any(test, feature = "test-seams"))]
    pub(crate) fn reset_relational_index_rebuild_rows_decoded_for_test() {
        RELATIONAL_INDEX_REBUILD_ROWS_DECODED.with(|count| count.set(0));
    }

    #[cfg(any(test, feature = "test-seams"))]
    pub(crate) fn relational_index_rebuild_rows_decoded_for_test() -> u64 {
        RELATIONAL_INDEX_REBUILD_ROWS_DECODED.with(std::cell::Cell::get)
    }

    fn load_vector_partition_table<T: serde::de::DeserializeOwned>(
        &self,
        definition: TableDefinition<&'static [u8], &'static [u8]>,
        kind: VectorPartitionRecordKind,
        expected_key: impl Fn(&T) -> Vec<u8>,
    ) -> Result<Vec<T>> {
        self.with_db(|db| {
            let read_txn = db.begin_read().map_err(Self::storage_error)?;
            self.load_vector_partition_table_in_read(
                &read_txn,
                definition,
                kind,
                expected_key,
                None,
            )
        })
    }

    pub(crate) fn load_vector_partition_memberships(
        &self,
    ) -> Result<Vec<VectorPartitionMembershipRecord>> {
        self.load_vector_partition_table(
            VECTOR_PARTITION_MEMBERSHIP_TABLE,
            VectorPartitionRecordKind::Membership,
            Self::vector_partition_membership_key,
        )
    }

    pub(crate) fn stream_vector_partition_memberships<T>(
        &self,
        partition: &VectorPartitionRef,
        dimension: usize,
        quantization: VectorQuantization,
        prepare: impl FnOnce(usize) -> Result<T>,
        mut visit: impl FnMut(
            &mut T,
            VectorPartitionMembershipRecord,
            &mut dyn FnMut(&VectorPartitionMembershipRecord) -> Result<VectorEntry>,
        ) -> Result<()>,
    ) -> Result<T> {
        self.with_db(|db| {
            let read = db.begin_read().map_err(Self::storage_error)?;
            // Memberships and bodies share this pinned root. The callback must
            // never reacquire persistence ownership while close/recycle waits.
            let mut load_body = |membership: &VectorPartitionMembershipRecord| {
                let mut entries = self.load_vector_entries_for_memberships_in_read(
                    &read,
                    std::slice::from_ref(membership),
                    dimension,
                    Some(quantization),
                )?;
                Ok(entries.pop().expect("one membership loads one body"))
            };
            stream_raw_partition_memberships(
                &read,
                partition,
                prepare,
                |state, membership| visit(state, membership, &mut load_body),
                |reason| self.vector_partition_corruption(reason),
            )
        })
    }

    pub(crate) fn load_vector_partition_memberships_for(
        &self,
        index: &VectorIndexRef,
        partition_key: &VectorPartitionKey,
    ) -> Result<Vec<VectorPartitionMembershipRecord>> {
        let prefix = Self::vector_partition_prefix(index, partition_key);
        self.with_db(|db| {
            let read_txn = db.begin_read().map_err(Self::storage_error)?;
            self.load_vector_partition_table_in_read(
                &read_txn,
                VECTOR_PARTITION_MEMBERSHIP_TABLE,
                VectorPartitionRecordKind::Membership,
                Self::vector_partition_membership_key,
                Some(&prefix),
            )
        })
    }

    /// Materialize only the admitted raw prefix, holding one decoded
    /// membership at a time rather than a partition-sized metadata clone.
    pub(crate) fn load_vector_partition_entries_at_frontier(
        &self,
        partition: &VectorPartitionRef,
        covered_tx: TxId,
        dimension: usize,
        raw_count: usize,
    ) -> Result<Vec<VectorEntry>> {
        let prefix = Self::vector_partition_prefix(&partition.index, &partition.partition_key);
        self.with_db(|db| {
            let read = db.begin_read().map_err(Self::storage_error)?;
            let memberships = match read.open_byte_table_bounded(VECTOR_PARTITION_MEMBERSHIP_TABLE)
            {
                Ok(table) => table,
                Err(redb::TableError::TableDoesNotExist(_)) => return Ok(Vec::new()),
                Err(error) => return Err(Self::storage_error(error)),
            };
            let mut entries = Vec::with_capacity(raw_count);
            for record in memberships
                .prefix_bounded(prefix.as_slice())
                .map_err(Self::storage_error)?
            {
                let (key, value) = record.map_err(Self::storage_error)?;
                if !key.value().starts_with(&prefix) {
                    break;
                }
                let membership: VectorPartitionMembershipRecord = self
                    .decode_expected_vector_partition_metadata(
                        VectorPartitionRecordKind::Membership,
                        value.value(),
                        &partition.index,
                        &partition.partition_key,
                    )?;
                if Self::vector_partition_membership_key(&membership).as_slice() != key.value() {
                    return Err(self.vector_partition_corruption(
                        "maintenance membership key disagrees with its payload",
                    ));
                }
                if membership.vector_created_tx > covered_tx {
                    continue;
                }
                let mut body = self.load_vector_entries_for_memberships_in_read(
                    &read,
                    std::slice::from_ref(&membership),
                    dimension,
                    None,
                )?;
                entries.push(body.pop().expect("one membership loads one body"));
            }
            Ok(entries)
        })
    }

    /// Load only membership versions for one row in one exact partition.
    /// The durable key is partition-first and then row-first, so unrelated
    /// rows in even a very large partition are never decoded for a point
    /// vector lookup.
    pub(crate) fn load_vector_partition_memberships_for_row(
        &self,
        index: &VectorIndexRef,
        partition_key: &VectorPartitionKey,
        row_id: RowId,
    ) -> Result<Vec<VectorPartitionMembershipRecord>> {
        let prefix = Self::vector_partition_membership_row_prefix(index, partition_key, row_id);
        self.with_db(|db| {
            let read_txn = db.begin_read().map_err(Self::storage_error)?;
            self.load_vector_partition_table_in_read(
                &read_txn,
                VECTOR_PARTITION_MEMBERSHIP_TABLE,
                VectorPartitionRecordKind::Membership,
                Self::vector_partition_membership_key,
                Some(&prefix),
            )
        })
    }

    /// Point-load exactly the vector bodies named by one checksummed
    /// partition directory. The membership table supplies placement and
    /// effective visibility; the vector table remains the body authority.
    pub(crate) fn load_vector_entries_for_memberships(
        &self,
        memberships: &[VectorPartitionMembershipRecord],
        expected_dimension: usize,
        quantization: Option<VectorQuantization>,
    ) -> Result<Vec<VectorEntry>> {
        if memberships.is_empty() {
            return Ok(Vec::new());
        }
        self.with_db(|db| {
            let read_txn = db.begin_read().map_err(Self::storage_error)?;
            self.load_vector_entries_for_memberships_in_read(
                &read_txn,
                memberships,
                expected_dimension,
                quantization,
            )
        })
    }

    fn load_vector_entries_for_memberships_in_read(
        &self,
        read_txn: &redb::ReadTransaction,
        memberships: &[VectorPartitionMembershipRecord],
        expected_dimension: usize,
        quantization: Option<VectorQuantization>,
    ) -> Result<Vec<VectorEntry>> {
        let verifier = quantization
            .map(|_| {
                content_identity::ContentIdentityReadVerifier::open(
                    read_txn,
                    &self.path,
                    self.proof_accountant(),
                )
            })
            .transpose()?;
        let mut proof = content_identity::ReadAuthenticationNodes::new(
            RAW_VECTOR_BODY_SCAN_PROOF_BYTES,
            self.proof_accountant(),
        );
        let table = match read_txn.open_byte_table_bounded(VECTORS_TABLE) {
            Ok(table) => table,
            Err(redb::TableError::TableDoesNotExist(_)) => {
                return Err(self.vector_partition_corruption(
                    "a non-empty raw-vector directory has no vector body table",
                ));
            }
            Err(error) => return Err(Self::storage_error(error)),
        };
        let mut entries = Vec::with_capacity(memberships.len());
        for membership in memberships {
            let key = Self::vector_identity_key(
                &membership.index,
                membership.row_id,
                membership.vector_created_tx,
                membership.vector_lsn,
            );
            let stored = table
                .get_bounded(key.as_slice())
                .map_err(Self::storage_error)?
                .ok_or_else(|| {
                    self.vector_partition_corruption(
                        "a raw-vector directory identity has no durable body",
                    )
                })?;
            self.validate_raw_vector_entry_encoded_width(
                stored.value(),
                &membership.index,
                expected_dimension,
            )?;
            let persisted: PersistedVectorEntry =
                Self::decode(stored.value()).map_err(|error| {
                    self.vector_partition_corruption(format!(
                        "a raw-vector directory body cannot be decoded: {error}"
                    ))
                })?;
            if persisted.index != membership.index
                || persisted.row_id != membership.row_id
                || persisted.created_tx != membership.vector_created_tx
                || persisted.lsn != membership.vector_lsn
            {
                return Err(self.vector_partition_corruption(
                    "a raw-vector body disagrees with its membership identity",
                ));
            }
            // Validate the exact length that to_f32 will produce BEFORE its
            // clone/dequantization allocation. A corrupt SQ4 coded payload
            // can fit the encoded-width bound yet expand beyond the declared
            // F32 scratch unless its predicted dimension is checked here.
            let decoded_bytes = persisted.vector.decoded_bytes();
            let decoded_dimension = decoded_bytes / std::mem::size_of::<f32>();
            if decoded_dimension != expected_dimension {
                return Err(self.vector_partition_corruption(format!(
                    "raw-vector body dimension {} does not match declared dimension {expected_dimension}",
                    decoded_dimension
                )));
            }
            crate::read_image_memory::reserve(decoded_bytes).map_err(|error| {
                self.vector_partition_corruption(format!(
                    "a raw-vector directory body cannot be decoded: {error}"
                ))
            })?;
            let mut entry = VectorEntry {
                index: persisted.index,
                row_id: persisted.row_id,
                vector: persisted.vector.to_f32(),
                created_tx: persisted.created_tx,
                deleted_tx: persisted.deleted_tx,
                lsn: persisted.lsn,
            };
            // Membership combines row and vector lifecycle. A row may
            // make the occurrence unavailable before the body receives
            // its own tombstone, so the effective partition visibility is
            // the checksummed membership value.
            entry.deleted_tx = membership.deleted_tx;
            if let (Some(verifier), Some(quantization)) = (&verifier, quantization) {
                verifier.verify_with_nodes(
                    &mut proof,
                    &content_identity::decoded_vector_version_mutation(&entry, quantization),
                )?;
                if entry.deleted_tx.is_none() {
                    verifier.verify_with_nodes(
                        &mut proof,
                        &content_identity::decoded_vector_mutation(&entry, quantization),
                    )?;
                }
            }
            entries.push(entry);
        }
        Ok(entries)
    }

    fn validate_raw_vector_entry_encoded_width(
        &self,
        bytes: &[u8],
        index: &VectorIndexRef,
        dimension: usize,
    ) -> Result<()> {
        validate_raw_vector_entry_encoded_width(bytes, index, dimension, |reason| {
            self.vector_partition_corruption(reason)
        })
    }

    pub(crate) fn open_raw_vector_body_scan(self: &Arc<Self>) -> Result<WritableRawVectorBodyScan> {
        self.with_db(|db| {
            let transaction = db.begin_read().map_err(Self::storage_error)?;
            let memberships = match transaction.open_table(VECTOR_PARTITION_MEMBERSHIP_TABLE) {
                Ok(table) => Some(table),
                Err(redb::TableError::TableDoesNotExist(_)) => None,
                Err(error) => return Err(Self::storage_error(error)),
            };
            let vectors = match transaction.open_table(VECTORS_TABLE) {
                Ok(table) => Some(table),
                Err(redb::TableError::TableDoesNotExist(_)) => None,
                Err(error) => return Err(Self::storage_error(error)),
            };
            let verifier = content_identity::ContentIdentityReadVerifier::open(
                &transaction,
                &self.path,
                self.proof_accountant(),
            )?;
            Ok(WritableRawVectorBodyScan {
                source: Arc::clone(self),
                memberships,
                vectors,
                verifier,
                proof: content_identity::ReadAuthenticationNodes::new(
                    RAW_VECTOR_BODY_SCAN_PROOF_BYTES,
                    self.proof_accountant(),
                ),
                _transaction: transaction,
            })
        })
    }

    /// Read one durable vector body through its exact partition, row, vector
    /// transaction, deletion transaction, and LSN identity. The membership
    /// range is row-prefixed, so this never enumerates another row in the
    /// partition, and exactly one body is decoded after placement validation.
    pub(crate) fn load_vector_entry_for_partition_identity(
        self: &Arc<Self>,
        index: &VectorIndexRef,
        partition_key: &VectorPartitionKey,
        identity: &RawVectorDirectoryEntry,
        expected_dimension: usize,
        quantization: VectorQuantization,
    ) -> Result<VectorEntry> {
        self.open_raw_vector_body_scan()?.read_partition_body(
            index,
            partition_key,
            identity,
            expected_dimension,
            quantization,
        )
    }

    /// Enumerate catalog pointers without making one bad record a database
    /// boundary. Exact known physical keys own their fault; otherwise only a
    /// fully checksummed, decoded payload may identify the affected route.
    pub(crate) fn inspect_vector_partition_generation_catalog(
        &self,
        known_routes: &[VectorPartitionRef],
    ) -> Result<LoadedVectorPartitionGenerationCatalog> {
        let known_by_key = known_routes
            .iter()
            .cloned()
            .map(|route| {
                (
                    Self::vector_partition_catalog_key_from_parts(
                        &route.index,
                        &route.partition_key,
                    ),
                    route,
                )
            })
            .collect::<HashMap<_, _>>();
        self.with_db(|db| {
            let read = db.begin_read().map_err(Self::storage_error)?;
            let table =
                match read.open_byte_table_bounded(VECTOR_PARTITION_GENERATION_CATALOG_TABLE) {
                    Ok(table) => table,
                    Err(redb::TableError::TableDoesNotExist(_)) => {
                        return Ok(LoadedVectorPartitionGenerationCatalog {
                            catalogs: Vec::new(),
                            quarantines: Vec::new(),
                        });
                    }
                    Err(error) => return Err(Self::storage_error(error)),
                };
            let mut catalogs = Vec::new();
            let mut quarantines = HashMap::<VectorPartitionRef, VectorRouteQuarantineReason>::new();
            for entry in table.iter().map_err(Self::storage_error)? {
                let (key, value) = entry.map_err(Self::storage_error)?;
                let physical_key = key.value();
                let physical_route = known_by_key.get(physical_key).cloned();
                match self.decode_vector_partition_record::<VectorPartitionGenerationCatalogRecord>(
                    VectorPartitionRecordKind::GenerationCatalog,
                    value.value(),
                ) {
                    Ok(catalog) => {
                        let payload_route = VectorPartitionRef::new(
                            catalog.index.clone(),
                            catalog.partition_key.clone(),
                        );
                        if Self::vector_partition_catalog_key(&catalog).as_slice() != physical_key {
                            let route = physical_route.unwrap_or(payload_route);
                            quarantines
                                .entry(route)
                                .or_insert(VectorRouteQuarantineReason::CorruptBase);
                        } else {
                            catalogs.push(catalog);
                        }
                    }
                    Err(_) => {
                        if let Some(route) = physical_route {
                            let reason = vector_generation_catalog_fault_reason(value.value());
                            quarantines
                                .entry(route)
                                .and_modify(|current| {
                                    if reason == VectorRouteQuarantineReason::IncompatibleFormat {
                                        *current = reason;
                                    }
                                })
                                .or_insert(reason);
                        }
                    }
                }
            }
            catalogs.retain(|catalog| {
                !quarantines.contains_key(&VectorPartitionRef::new(
                    catalog.index.clone(),
                    catalog.partition_key.clone(),
                ))
            });
            let mut quarantines = quarantines.into_iter().collect::<Vec<_>>();
            quarantines.sort_by(|(left, _), (right, _)| {
                left.index
                    .table
                    .cmp(&right.index.table)
                    .then(left.index.column.cmp(&right.index.column))
                    .then(
                        left.partition_key
                            .canonical_bytes()
                            .cmp(&right.partition_key.canonical_bytes()),
                    )
            });
            Ok(LoadedVectorPartitionGenerationCatalog {
                catalogs,
                quarantines,
            })
        })
    }

    /// Maintenance pins one committed root and separates navigation from
    /// materialization. Only a selected singleton's resource refusal may be
    /// handled locally by the caller; navigation errors remain terminal.
    pub(crate) fn scan_vector_catalog_for_maintenance(
        &self,
        mut inspect: impl FnMut(redb::BoundedByteHandle<'_>) -> Result<()>,
    ) -> Result<()> {
        self.with_db(|db| {
            let read = db.begin_read().map_err(Self::storage_error)?;
            let table =
                match read.open_byte_table_bounded(VECTOR_PARTITION_GENERATION_CATALOG_TABLE) {
                    Ok(table) => table,
                    Err(redb::TableError::TableDoesNotExist(_)) => return Ok(()),
                    Err(error) => return Err(Self::storage_error(error)),
                };
            for handle in table.cursor_bounded() {
                inspect(handle.map_err(Self::storage_error)?)?;
            }
            Ok(())
        })
    }

    pub(crate) fn decode_maintenance_vector_catalog(
        &self,
        encoded: &[u8],
    ) -> Result<VectorPartitionGenerationCatalogRecord> {
        self.decode_vector_partition_record(VectorPartitionRecordKind::GenerationCatalog, encoded)
    }

